from requests.utils import get_netrc_auth

def test_netrc_variants():
    netrc_path = "/tmp/.netrc_test"

    cases = [
        ("machine example.com login pass\n", "http://example.com", ("login", "pass"), "full entry"),
        ("machine example.com : pass\n", "http://example.com", ("", "pass"), "empty login"),
        ("machine example.com login :\n", "http://example.com", ("login", ""), "empty password"),
        ("machine example.com\n", "http://example.com", None, "empty entry"),
        ("machine other.com login pass\n", "http://example.com", None, "different host"),
    ]

    for content, url, expected, name in cases:
