import requests
from collections.abc import Iterable

class ProxyIterable:
    def __init__(self, data):
        self._data = data
    def __getattr__(self, name):
        return getattr(self._data, name)
    def __iter__(self):
        return iter(self._data)

def test_proxy_iterable():
    # This should be detected as a stream because it has __iter__ 
    # but is not an instance of Iterable (unless registered)
    data = ProxyIterable([b"hello", b"world"])

    # We want to see if prepare_body treats it as a stream.
    # In requests, if it's treated as a stream, it's assigned to self._body
    # and not processed as form data.

    req = requests.Request('POST', 'http://httpbin.org/post', data=data)
    prep = req.prepare()

    # If it was treated as a stream, prep.body should be the ProxyIterable instance
    assert prep.body is data
    print("Success: ProxyIterable detected as stream")

if __name__ == "__main__":
    try:
        test_proxy_iterable()
    except Exception as e:
        print(f"Failure: {e}")
        exit(1)
